contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address adr, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(adr != address(0));
        require(adr != address(this));

        uint256 balBeforeC = address(c).balance;
        uint256 balBeforeAdr = address(adr).balance;
        uint256 msgValue = amount;

        c.multiplicate{value: amount}(adr); if (__ESBMC_reverted()) return;

        uint256 balAfterC = address(c).balance;
        uint256 balAfterAdr = address(adr).balance;

        uint256 transferred = balAfterAdr - balBeforeAdr;
        uint256 expectedC = balBeforeC + msgValue - transferred;

        assert(balAfterC == expectedC);
    }
}

