// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(address adr, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(adr != address(0));
        vm.assume(adr != address(this));
        uint256 balBeforeC = address(c).balance;
        uint256 balBeforeAdr = address(adr).balance;
        uint256 msgValue = amount;
        try c.multiplicate{value: amount}(adr) {} catch { return; }
        uint256 balAfterC = address(c).balance;
        uint256 balAfterAdr = address(adr).balance;
        uint256 transferred = balAfterAdr - balBeforeAdr;
        uint256 expectedC = balBeforeC + msgValue - transferred;
        assertTrue(balAfterC == expectedC);
    }

    function testFuzz_run(address adr, uint256 amount) public {
        vm.assume(adr.code.length == 0 && uint160(adr) > 0xffff && adr != address(this) && adr != address(c) && adr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && adr != 0x000000000000000000636F6e736F6c652e6c6f67 && adr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && adr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(adr, amount);
    }

    receive() external payable {}
}
